def trade(name,price_tea,price_cut):
    S('trade_'+name,{
     'start':N('zina','Зинаида подмигивает: «Милок, есть товар. Пачка чая — %d рублей. %s».'%(price_tea,{'low':'Тебе — по цене для своих... то есть не для своих','mid':'Цена честная','high':'Для вас — особая скидка, уважаемый'}[name]),
      ch('Купить пачку чая (%d ₽)'%price_tea,R('Чай — это валюта нового мира.',{'rub':-price_tea,'item':{'tea':1}}),req={'rub':price_tea}),
      ch('Сбить цену до %d ₽ (харизма)'%price_cut,R('Зинаида фыркает, но сдаётся.',{'rub':-price_cut,'item':{'tea':1},'cha':1}),R('Зинаида: «Дорого? Ну и не надо!»',{}),chk=(H,14),req={'rub':price_cut}),
      ch('Отказаться',R('Зинаида пожимает плечами.',{})))},title='Торговля')
trade('low',24,16);trade('mid',15,10);trade('high',10,6)
def exch(name,buy,sell):
    S('exchange_'+name,{
     'start':N('buh','Бухгалтер водит пальцем по таблице. «Сегодня чай: покупка %d ₽, продажа %d ₽. Рынок — это вам не пайка».'%(buy,sell),
      ch('Продать пачку чая (+%d ₽)'%sell,R('Сделка заключена. Бухгалтер что-то записал.',{'item':{'tea':-1},'rub':sell,'rel':{'buh':1}}),req={'item_tea':1}),
      ch('Купить пачку чая (−%d ₽)'%buy,R('Пачка переходит в ваши руки.',{'rub':-buy,'item':{'tea':1}}),req={'rub':buy}),
      ch('Угадать завтрашний курс (мудрость)',R('Вы чувствуете тренд. Бухгалтер впечатлён.',{'rep':1,'rel':{'buh':3}}),R('Ваш прогноз мимо. Бухгалтер вздыхает.',{}),chk=(W,13)),
      ch('Уйти',R('Рынок подождёт.',{})))},title='Биржа чая')
for _n,(_b,_s) in MARKET.items():exch(_n,_b,_s)
