def weak_scenes(b,w_txt,stat,dc,win,lose):
    """Пара сцен для босса b: «Разведка» (узнать слабость) и «Слабое место» (свергнуть без драки)."""
    S('scout_'+b,{
     'start':N(b,'Вы начинаете незаметно изучать повадки. У каждого босса есть слабое место — осталось его найти.',
      ch('Наблюдать издали (мудрость)',R('Вы заметили главное: %s.'%w_txt,{'learn_weak':b}),R('Вас заметили, и наблюдение пришлось прервать.',{'rel':{b:-2}}),chk=(W,12)),
      ch('Расспросить жителей (2 сиг.)',R('Люди охотно делятся наблюдениями: %s.'%w_txt,{'cig':-2,'learn_weak':b}),req={'cig':2}),
      ch('Отложить',R('Босс никуда не денется.',{})))},rep=True,title='Разведка')
    S('weak_'+b,{
     'start':N(b,'Вы знаете слабость: %s. Пора действовать без кулаков.'%w_txt,
      ch('Воспользоваться слабостью',R(win,{'ouster':b,'caste':4,'flag':'weak_%s_used'%b,'rep':4}),R(lose,{'rel':{b:-8},'hp':-4,'caste':-2}),chk=(stat,dc-2)),
      ch('Передумать',R('Вы решаете подождать.',{})))},rep=True,title='Слабое место')
for b,row in list(WEAK.items()):weak_scenes(b,*row)
